                 work_tile_info.is_valid(params.scheduler);
                 ) {
                auto block_coord = work_tile_info.get_block_coord(params.scheduler);
                ...
                work_tile_info = scheduler.template get_next_work</*IsProducerWarp=*/false>(params.scheduler, work_tile_info);
                ...
                if (tile_valid) {
                    epilogue.store(..., block_coord);
                } else {
                    epilogue.store_zero(..., block_coord);
                }
            }
```

**Validity checks differ by scheduler:**
- Static/Dynamic: `tile_idx < total_blocks`
- Varlen: `bidb < num_batch` (sentinel `bidb = num_batch` means done)
- SingleTile: `bidb >= 0` (invalid tiles set `bidb = -1`)

### StaticPersistent stride (no atomic)

```200:218:/home/yak/data-fast/agent/reference/libraries/vllm-flash-attention/hopper/tile_scheduler.hpp
    get_initial_work(Params const& params) const {
        return {int(blockIdx.x)};
    }
    ...
    get_next_work(Params const& params, WorkTileInfo const& current_work) const {
        return {current_work.tile_idx + int(gridDim.x)};
    }
```

CTA `i` processes tiles `i, i+num_sm, i+2·num_sm, …`. Flat index decodes to `(m_block, head, batch[, split])`:

```160:190:/home/yak/data-fast/agent/reference/libraries/vllm-flash-attention/hopper/tile_scheduler.hpp
        return {args.num_blocks * args.num_head * args.num_batch * (!Split ? 1 : args.num_splits),
                cutlass::FastDivmod(args.num_blocks), cutlass::FastDivmod(args.num_head * (!Split ? 1 : args.num_splits)),
                cutlass::FastDivmod(!Split ? 1 : args.num_splits)};
    ...
        get_block_coord(Params const& params) const {
            int block, bidh, bidb;
            bidb = params.head_divmod.divmod(bidh, params.m_block_divmod.divmod(block, tile_idx));
            int split_idx = 0;
            if constexpr (Split) {
                bidh = params.nsplits_divmod.divmod(split_idx, bidh);
            }
            return {block, bidh, bidb, split_idx};
        }
```

**Tile index order (Static/Dynamic dense):** row-major over `(batch, head×split, m_block)` with `m_block` innermost (via successive divmods).

